-- t278b: COMMENT documentation for the gold schema of packiot_analytics (staging).
-- OEE = Availability (oee_a) x Performance (oee_p) x Quality (oee_q); all factors clamped to [0,1].
-- Grounded in stream-engine internal/rollup/*.go + pocontrol + barcode-service. Idempotent; non-destructive.

COMMENT ON TABLE gold.equipment_oee_hourly IS 'Gold OEE grain: one row per (id_equipment, hour). Foundation grain of the rollup cascade, computed by stream-engine internal/rollup/hour.go (runtime-rollup-hour). Exists only for lines/sectors (tp_equipment > 1); tp=1 machines are rolled up at shift/day, never hourly. gross/net/speed from the 1h categorical cagg (phase V); time-in-state + Availability/Quality from equipment_events overlaps (phase E); ideal_speed from the 1min tier LOCF. Composite oee and oee_a/oee_p/oee_q are clamped to [0,1] and satisfy oee = oee_a*oee_p*oee_q (CHECK *_oee_bounds).';
COMMENT ON COLUMN gold.equipment_oee_hourly.id_equipment IS 'FK -> equipments. The equipment (line/sector/machine) this grain row belongs to.';
COMMENT ON COLUMN gold.equipment_oee_hourly.ts_value IS 'Bucket start / anchor timestamp for this grain row (part of the natural key).';
COMMENT ON COLUMN gold.equipment_oee_hourly.oee IS 'Composite OEE ratio in [0,1] (CHECK oee_bounds); = oee_a*oee_p*oee_q. NULL for tp=1 machines of LINE-metered enterprises (unmetered.go: ''not metered'' rather than a misleading 0). Clamped to [0,1].';
COMMENT ON COLUMN gold.equipment_oee_hourly.recalc_needed IS 'Dirty flag: true => this row will be recomputed on the next rollup tick. Cleared by the compute pass, re-set by the tail re-flag for recent/current buckets.';
COMMENT ON COLUMN gold.equipment_oee_hourly.oee_p IS 'Performance factor, ratio in [0,1] (CHECK oee_bounds). Throughput vs ideal speed; back-solved as oee/(oee_a*oee_q) or, under the canonical reconcile, gross*available/(ideal_production*running). Clamped to [0,1].';
COMMENT ON COLUMN gold.equipment_oee_hourly.oee_a IS 'Availability factor, ratio in [0,1] (CHECK oee_bounds). = running_time / scheduled-production-time (available window). Clamped to [0,1].';
COMMENT ON COLUMN gold.equipment_oee_hourly.oee_q IS 'Quality factor, ratio in [0,1] (CHECK oee_bounds). = net / gross (good units over produced units). Clamped to [0,1].';
COMMENT ON COLUMN gold.equipment_oee_hourly.available_time IS 'Scheduled production time in SECONDS = bucket wall-clock span - planned_downtime (LEAST-guarded >= 0). Denominator of Availability.';
COMMENT ON COLUMN gold.equipment_oee_hourly.running_time IS 'Time in the RUNNING state (equipment_events status=6) in SECONDS, capped at the bucket span (LEAST) so overlapping line/member events cannot exceed elapsed wall-clock.';
COMMENT ON COLUMN gold.equipment_oee_hourly.stopped_time IS 'Time in STOPPED states (equipment_events status IN (5,10,11)) in SECONDS.';
COMMENT ON COLUMN gold.equipment_oee_hourly.planned_downtime IS 'Time in PLANNED-downtime events in SECONDS (capped at the bucket span). Subtracted from wall-clock to yield available_time.';
COMMENT ON COLUMN gold.equipment_oee_hourly.ideal_production IS 'Theoretical ideal-speed output over the available window, in COUNT units = (available_time/60) * ideal_speed. Denominator of Performance; a raw oee_p>1 means ideal_speed is set too low.';
COMMENT ON COLUMN gold.equipment_oee_hourly.idle_time IS 'Idle time in SECONDS. Summed up the grain cascade but NOT populated by any base-grain writer in the new-stack stream-engine (dormant / 0 on staging).';
COMMENT ON COLUMN gold.equipment_oee_hourly.idle_starved IS 'Starvation idle (no infeed) in SECONDS. Summed up the cascade only; no base-grain writer in the new stack (dormant / 0 on staging).';
COMMENT ON COLUMN gold.equipment_oee_hourly.idle_blocked IS 'Blocking idle (no outfeed) in SECONDS. Summed up the cascade only; no base-grain writer in the new stack (dormant / 0 on staging).';
COMMENT ON COLUMN gold.equipment_oee_hourly.target IS 'Production target for the bucket, in COUNT units (from core.production_targets). 0 when no target; NOT overwritten while target_customized is true.';
COMMENT ON COLUMN gold.equipment_oee_hourly.gross IS 'Gross produced count for the bucket = SUM(gross_production_incr) from the categorical cagg. COUNT units.';
COMMENT ON COLUMN gold.equipment_oee_hourly.net IS 'Good (net) produced count for the bucket = SUM(net_production_incr). COUNT units. net <= gross.';
COMMENT ON COLUMN gold.equipment_oee_hourly.downtime IS 'Time in ANY non-running state (equipment_events status <> 6) in SECONDS (capped at bucket span).';
COMMENT ON COLUMN gold.equipment_oee_hourly.changeover_time IS 'Time in CHANGEOVER events (change_over=true) in SECONDS (capped at bucket span).';
COMMENT ON COLUMN gold.equipment_oee_hourly.scrap IS 'Rejected/scrap count = gross - net (COALESCE 0). COUNT units.';
COMMENT ON COLUMN gold.equipment_oee_hourly.speed IS 'Average production speed over the bucket in COUNT-per-minute (avg of sum_speed/cnt_speed; shift grain averages state=6 buckets only).';
COMMENT ON COLUMN gold.equipment_oee_hourly.ts_value_production IS 'Production-day DATE this bucket belongs to (shift day anchor via piot_get_day_begin_by_*). Used to key the shift value/target passes.';
COMMENT ON COLUMN gold.equipment_oee_hourly.target_customized IS 'If true, target / proportional_target were set manually and the rollup will NOT overwrite them.';
COMMENT ON COLUMN gold.equipment_oee_hourly.proportional_target IS 'Elapsed-prorated production target in COUNT units for the (live) bucket. Hour = vl_day/24; shift = vl_day * (elapsed scheduled-productive time)/86400 so a live shift scales with elapsed and a completed shift settles at the full target. 0 / not overwritten when target_customized.';
COMMENT ON COLUMN gold.equipment_oee_hourly.id_team IS 'FK -> team assigned to this shift bucket (seeded from the shift calendar). Not written by the rollup metric passes.';
COMMENT ON COLUMN gold.equipment_oee_hourly.ideal_speed IS 'Ideal production speed in COUNT-per-minute, LOCF''d from PLC param 30701 (falls back to equipments.production_speed). Basis for ideal_production. 0 when unknown.';
COMMENT ON COLUMN gold.equipment_oee_hourly.computed_at IS 'Wall-clock time the rollup last WROTE this row (ADR-0036 5A lineage stamp). Distinct from source_watermark.';
COMMENT ON COLUMN gold.equipment_oee_hourly.source_watermark IS 'Latest event-time this row has visibility through = LEAST(bucket end, now()) (ADR-0036 5A). For a replayed old bucket, computed_at is recent while this settles at the bucket end.';

COMMENT ON TABLE gold.equipment_oee_shift IS 'Gold OEE grain: one row per (id_equipment, shift bucket). Computed by stream-engine internal/rollup/shift.go (runtime-rollup-shift). Covers tp>1 lines/sectors plus tp=1 machines of machine-level enterprises (UNION selector); line-metered tp=1 machines have their oee* NULLed by unmetered.go. Metric columns overwritten each tick; the shift-calendar columns (id_shift/id_shift_hour/id_team/duration/ts_range/ts_end/ts_value_production/target) are seeded by the DB provision procs. PK (id_equipment, ts_value); CHECK ts_value <= ts_end; CHECK oee_bounds [0,1].';
COMMENT ON COLUMN gold.equipment_oee_shift.id_runtime_shift IS 'Surrogate id; DEFAULT nextval from the legacy equipment_oee_shift_id_seq sequence (still live). Not the primary key -- the PK is (id_equipment, ts_value).';
COMMENT ON COLUMN gold.equipment_oee_shift.ts_value IS 'Bucket start / anchor timestamp for this grain row (part of the natural key).';
COMMENT ON COLUMN gold.equipment_oee_shift.id_equipment IS 'FK -> equipments. The equipment (line/sector/machine) this grain row belongs to.';
COMMENT ON COLUMN gold.equipment_oee_shift.oee IS 'Composite OEE ratio in [0,1] (CHECK oee_bounds); = oee_a*oee_p*oee_q. NULL for tp=1 machines of line-metered enterprises (unmetered.go). Clamped to [0,1].';
COMMENT ON COLUMN gold.equipment_oee_shift.recalc_needed IS 'Dirty flag: true => this row will be recomputed on the next rollup tick. Cleared by the compute pass, re-set by the tail re-flag for recent/current buckets.';
COMMENT ON COLUMN gold.equipment_oee_shift.oee_p IS 'Performance factor, ratio in [0,1] (CHECK oee_bounds). Throughput vs ideal speed; back-solved as oee/(oee_a*oee_q) or, under the canonical reconcile, gross*available/(ideal_production*running). Clamped to [0,1].';
COMMENT ON COLUMN gold.equipment_oee_shift.oee_a IS 'Availability factor, ratio in [0,1] (CHECK oee_bounds). = running_time / scheduled-production-time (available window). Clamped to [0,1].';
COMMENT ON COLUMN gold.equipment_oee_shift.oee_q IS 'Quality factor, ratio in [0,1] (CHECK oee_bounds). = net / gross (good units over produced units). Clamped to [0,1].';
COMMENT ON COLUMN gold.equipment_oee_shift.available_time IS 'Scheduled production time in SECONDS = bucket wall-clock span - planned_downtime (LEAST-guarded >= 0). Denominator of Availability.';
COMMENT ON COLUMN gold.equipment_oee_shift.running_time IS 'Time in the RUNNING state (equipment_events status=6) in SECONDS, capped at the bucket span (LEAST) so overlapping line/member events cannot exceed elapsed wall-clock.';
COMMENT ON COLUMN gold.equipment_oee_shift.stopped_time IS 'Time in STOPPED states (equipment_events status IN (5,10,11)) in SECONDS.';
COMMENT ON COLUMN gold.equipment_oee_shift.planned_downtime IS 'Time in PLANNED-downtime events in SECONDS (capped at the bucket span). Subtracted from wall-clock to yield available_time.';
COMMENT ON COLUMN gold.equipment_oee_shift.ideal_production IS 'Theoretical ideal-speed output over the available window, in COUNT units = (available_time/60) * ideal_speed. Denominator of Performance; a raw oee_p>1 means ideal_speed is set too low.';
COMMENT ON COLUMN gold.equipment_oee_shift.idle_time IS 'Idle time in SECONDS. Summed up the grain cascade but NOT populated by any base-grain writer in the new-stack stream-engine (dormant / 0 on staging).';
COMMENT ON COLUMN gold.equipment_oee_shift.idle_starved IS 'Starvation idle (no infeed) in SECONDS. Summed up the cascade only; no base-grain writer in the new stack (dormant / 0 on staging).';
COMMENT ON COLUMN gold.equipment_oee_shift.idle_blocked IS 'Blocking idle (no outfeed) in SECONDS. Summed up the cascade only; no base-grain writer in the new stack (dormant / 0 on staging).';
COMMENT ON COLUMN gold.equipment_oee_shift.id_shift IS 'FK -> shifts. The shift definition for this bucket (seeded from the shift calendar).';
COMMENT ON COLUMN gold.equipment_oee_shift.id_shift_hour IS 'FK -> shift_hours. The specific shift-calendar row (shift x weekday expansion) for this bucket.';
COMMENT ON COLUMN gold.equipment_oee_shift.id_team IS 'FK -> team assigned to this shift bucket (seeded from the shift calendar). Not written by the rollup metric passes.';
COMMENT ON COLUMN gold.equipment_oee_shift.duration IS 'Scheduled shift length (shift_size) in SECONDS, seeded from the shift calendar. Not the elapsed/running time.';
COMMENT ON COLUMN gold.equipment_oee_shift.ts_range IS 'tstzrange span [start, end) of the shift bucket (seeded from the shift calendar).';
COMMENT ON COLUMN gold.equipment_oee_shift.gross IS 'Gross produced count for the bucket = SUM(gross_production_incr) from the categorical cagg. COUNT units.';
COMMENT ON COLUMN gold.equipment_oee_shift.net IS 'Good (net) produced count for the bucket = SUM(net_production_incr). COUNT units. net <= gross.';
COMMENT ON COLUMN gold.equipment_oee_shift.downtime IS 'Time in ANY non-running state (equipment_events status <> 6) in SECONDS (capped at bucket span).';
COMMENT ON COLUMN gold.equipment_oee_shift.changeover_time IS 'Time in CHANGEOVER events (change_over=true) in SECONDS (capped at bucket span).';
COMMENT ON COLUMN gold.equipment_oee_shift.target IS 'Production target for the bucket, in COUNT units (from core.production_targets). 0 when no target; NOT overwritten while target_customized is true.';
COMMENT ON COLUMN gold.equipment_oee_shift.ts_end IS 'End timestamp of the shift bucket. Upper bound used by the event-overlap phase; CHECK ts_value <= ts_end (on equipment_oee_shift).';
COMMENT ON COLUMN gold.equipment_oee_shift.manually_customized IS 'Legacy flag: row was manually edited (via edge-api/front4), not by the rollup. Default false; not written by the new-stack rollup.';
COMMENT ON COLUMN gold.equipment_oee_shift.invalidated IS 'Legacy flag: row marked invalid / excluded from reporting. Default false; not written by the new-stack rollup.';
COMMENT ON COLUMN gold.equipment_oee_shift.scrap IS 'Rejected/scrap count = gross - net (COALESCE 0). COUNT units.';
COMMENT ON COLUMN gold.equipment_oee_shift.speed IS 'Average production speed over the bucket in COUNT-per-minute (avg of sum_speed/cnt_speed; shift grain averages state=6 buckets only).';
COMMENT ON COLUMN gold.equipment_oee_shift.cd_shift IS 'Denormalized shift code (shifts.cd_shift, e.g. ''MORNING'',''T1''); refreshed from the calendar by the shift value pass.';
COMMENT ON COLUMN gold.equipment_oee_shift.ts_value_production IS 'Production-day DATE this bucket belongs to (shift day anchor via piot_get_day_begin_by_*). Used to key the shift value/target passes.';
COMMENT ON COLUMN gold.equipment_oee_shift.target_customized IS 'If true, target / proportional_target were set manually and the rollup will NOT overwrite them.';
COMMENT ON COLUMN gold.equipment_oee_shift.proportional_target IS 'Elapsed-prorated production target in COUNT units for the (live) bucket. Hour = vl_day/24; shift = vl_day * (elapsed scheduled-productive time)/86400 so a live shift scales with elapsed and a completed shift settles at the full target. 0 / not overwritten when target_customized.';
COMMENT ON COLUMN gold.equipment_oee_shift.ideal_speed IS 'Ideal production speed in COUNT-per-minute, LOCF''d from PLC param 30701 (falls back to equipments.production_speed). Basis for ideal_production. 0 when unknown.';
COMMENT ON COLUMN gold.equipment_oee_shift.computed_at IS 'Wall-clock time the rollup last WROTE this row (ADR-0036 5A lineage stamp). Distinct from source_watermark.';
COMMENT ON COLUMN gold.equipment_oee_shift.source_watermark IS 'Latest event-time this row has visibility through = LEAST(bucket end, now()) (ADR-0036 5A). For a replayed old bucket, computed_at is recent while this settles at the bucket end.';

COMMENT ON TABLE gold.equipment_oee_daily IS 'Gold OEE grain: one row per (id_equipment, production day). Flagged recalc_needed by the hour cascade (hour.go hourCascadeDaySQL) and rolled up from the underlying grain. Feeds the weekly/monthly cascade (grains.go) and the area/site day rollup (entity_grains.go). oee* clamped to [0,1] (CHECK oee_bounds).';
